a=[[3]*20 for _ in range(16)]
# 8 rectangular border
for c in range(11,18): a[1][c]=a[7][c]=8
for r in range(1,8): a[r][11]=a[r][17]=8
# 6 ring
for r,c in [(r,c) for r in range(3,6) for c in range(3) if r in (3,5) or c in (0,2)]: a[r][c]=6
# 1 ring
for r in range(2,5):
 for c in range(7,10):
  if r in (2,4) or c in (7,9): a[r][c]=1
# 6 ring lower left
for r in range(8,11):
 for c in range(1,4):
  if r in (8,10) or c in (1,3): a[r][c]=6
# 5 ring
for r in range(8,11):
 for c in range(5,8):
  if r in (8,10) or c in (5,7): a[r][c]=5
# large 6 outline
for r in range(9,15):
 for c in range(9,15):
  if r in (9,14) or c in (9,14): a[r][c]=6
# Fill all holes by parity
for r,c,v in [(4,1,7),(3,8,7),(9,2,7),(9,6,7)]: a[r][c]=v
for r in range(2,7):
 for c in range(12,17): a[r][c]=7
for r in range(10,14):
 for c in range(10,14): a[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in a))

# reconstruct original from modified a, setting interior fills back to 3
orig=[row[:] for row in a]
for r,c in [(4,1),(3,8),(9,2),(9,6)]: orig[r][c]=3
for r in range(2,7):
 for c in range(12,17): orig[r][c]=3
for r in range(10,14):
 for c in range(10,14): orig[r][c]=3
from collections import deque
R,C=len(orig),len(orig[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if orig[r][c]==3 and (r,c) not in seen:
   q=deque([(r,c)]); seen.add((r,c)); comp=[]
   while q:
    x,y=q.popleft(); comp.append((x,y))
    for xx,yy in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     if 0<=xx<R and 0<=yy<C and orig[xx][yy]==3 and (xx,yy) not in seen:
      seen.add((xx,yy));q.append((xx,yy))
   comps.append(comp)
[(len(q),min(x for x,y in q),max(x for x,y in q),min(y for x,y in q),max(y for x,y in q),any(x in(0,R-1) or y in(0,C-1) for x,y in q)) for q in comps]
